def discset(p):
    return set((p[0]+dr,p[1]+dc) for dr in (-2,-1,0,1,2) for dc in (-2,-1,0,1,2) if not (abs(dr)==2 and abs(dc)==2))

def bres(p,q):
    r0,c0=p; r1,c1=q; out=[(r0,c0)]
    dr=abs(r1-r0); dc=-abs(c1-c0); sr=1 if r0<r1 else -1; sc=1 if c0<c1 else -1; err=dr+dc
    for _ in range(200):
        if r0==r1 and c0==c1: break
        e2=2*err
        if e2>=dc: err+=dc; r0+=sr
        if e2<=dr: err+=dr; c0+=sc
        out.append((r0,c0))
    return out

def blobof(ps): return (sum(p[0] for p in ps)//len(ps), sum(p[1] for p in ps)//len(ps))

def ok(crosses, free):
    b = blobof(crosses)
    cells=set()
    for p in crosses+[b]:
        d=discset(p)
        if not d <= free: return False
        if d & cells: return False
        cells |= d
    for p in crosses:
        for cell in bres(b,p):
            if cell in cells: continue
            if cell not in free: return False
    return True

